/* From Uiverse.io by FahadArnob52539  - Tags: form, html, css */
.__UIV_SCOPE__ .login {
  max-width: 280px;
  background-color: #ffffff;
  border-radius: 5px;
}
.__UIV_SCOPE__ .hader {
  text-align: center;
  font-size: 22px;
  font-weight: 700;
}
.__UIV_SCOPE__ .hader p {
  text-align: center;
  font-size: 18px;
  font-weight: 400;
  color: #706b6b;
}
.__UIV_SCOPE__ form {
  display: flex;
  flex-direction: column;
  gap: 15px;
  margin-top: 20px;
}
.__UIV_SCOPE__ form input {
  height: 40px;
  outline: none;
  border: 1px solid #cccccc;
  padding: 10px;
  font-size: 15px;
  border-radius: 8px;
}
.__UIV_SCOPE__ form input[type="button"] {
  background-color: rgba(17, 17, 226, 0.562);
  color: #ffffff;
  font-size: 17px;
}
.__UIV_SCOPE__ form span {
  text-align: center;
  font-size: 16px;
  padding-top: 10px;
  color: #706b6b;
}
.__UIV_SCOPE__ form span a {
  text-decoration: none;
  color: rgba(36, 36, 207, 0.671);
  font-weight: 500;
}
